import sys,collections,heapq,itertools,functools,bisect
def solve(data):
    n=int(data);mask=(1<<n)-1
    def f(c,l,r):
        if c==mask:return 1
        v=mask&~(c|l|r);ans=0
        while v:
            x=v&-v;v-=x;ans+=f(c|x,((l|x)<<1)&mask,(r|x)>>1)
        return ans
    return f(0,0,0)

if __name__=="__main__":
    a=solve(sys.stdin.buffer.read().decode())
    print(" ".join(map(str,a)) if isinstance(a,(list,tuple)) else a)
